const HELP_GROUP_H = { cards: ['Cards & sharing', 'البطاقات والمشاركة'], import: ['Import', 'الاستيراد'], privacy: ['Your data & privacy', 'بياناتك وخصوصيتك'], howto: ['Copy a link', 'نسخ رابط'], settings: ['Settings', 'الإعدادات'], home: ['Home Screen', 'الشاشة الرئيسية'] };
const HELP_ACT = { places: '＋ Add place', trips: '＋ Build a trip', curators: 'Open Curators', community: 'Open Community', addresses: 'Open Addresses' }; /* فعل البطاقة باسم زره في الشاشة */
const HELP_TOPICS = [
  { id: 'places.basics', dest: 'places', tags: [], ui: [],
    en: { h: 'Cities, categories and adding from a link', b: 'Every place lives in one city and one sub-category (the tree is ours: cafés, dishes, cuisines, shopping, parks, squares, waterfronts, landmarks, family, stay, transport). Add a place from a Maps link: name and area fill in, the category is suggested, and the pin is placed for you — correct it with one drag.' },
    ar: { h: 'المدن والتصنيفات والإضافة من رابط', b: 'كل مكان بمدينة واحدة وفرعي واحد (الشجرة لنا: مقاهٍ · وجبات · مطابخ · تسوّق · حدائق · ساحات · واجهات بحرية · معالم · عائلة · إقامة · تنقل). أضف مكانًا من رابط الخرائط: يُملأ الاسم والمنطقة، ويُقترح التصنيف، ويُوضع الدبوس لك — صحّحه بسحبة.' } },
  { id: 'places.saving', dest: 'places', tags: ['r100-أ', 'r100-ب', 'r100-ج', 'r100-د', 'r100-و'], ui: ['Unsaved', 'MyPickz is busy today — back at 11:00 Riyadh'],
    en: { h: 'Saving, limits and messages', b: "If a save fails (no connection), a sheet asks Retry or Discard; a change you keep shows <b>Unsaved</b> next to My places until it saves. While a save or delete is running its button is disabled and a second tap is ignored — one tap, one change. Text fields have limits (name 120 · note 2,000 · nickname 24): a counter appears as you near the limit, and Save asks you to shorten rather than cutting your text. When something can't load or save, the message says why in plain words — check your connection, you don't have access, try again — and what was on screen stays; if the free daily quota runs out you'll see <b>MyPickz is busy today — back at 11:00 Riyadh</b>. A private daily backup of all data is taken at 11:30 Riyadh. Saving writes only the categories you touched, and keeps places added from another device." },
    ar: { h: 'الحفظ والحدود والرسائل', b: 'إن فشل الحفظ (بلا اتصال) تسألك ورقة Retry أو Discard؛ والتعديل الذي تُبقيه يظهر <b>Unsaved</b> بجانب My places حتى يُحفظ. وأثناء الحفظ أو الحذف يتعطّل الزر وتُتجاهل النقرة الثانية — نقرة واحدة، تغيير واحد. وللخانات حدود (الاسم ١٢٠ · الملاحظة ٢٠٠٠ · الاسم المستعار ٢٤): يظهر عدّاد حين تقترب من الحد، وSave يطلب الاختصار بدل أن يقصّ نصك. وحين يتعذّر تحميل شيء أو حفظه تقول الرسالة السبب بكلمات واضحة — تحقق من الاتصال · لا صلاحية · حاول مجددًا — ويبقى ما على الشاشة؛ وإن نفدت الحصة اليومية المجانية ترى <b>MyPickz is busy today — back at 11:00 Riyadh</b>. ونسخة احتياطية خاصة من كل البيانات تُؤخذ يوميًا ١١:٣٠ الرياض. الحفظ يكتب التصنيفات التي مسستها فقط ويُبقي ما أضافه جهاز آخر.' } },
  { id: 'places.list', dest: 'places', tags: [], ui: ['List', 'Map', '📍 Nearby', 'Go'],
    en: { h: 'Your list: filter, map and Nearby', b: "Your list shows sections you have content in, with counts. Filter by category, then sub-category. Switch <b>☰ List · 🗺 Map</b>; <b>📍 Nearby</b> (beside Day plan) sorts this city's places by straight-line distance from where you are — ≤ 1 km · ≤ 3 km · Any — with a <i>Go</i> button in your navigation app. Your location is asked when you tap and never stored." },
    ar: { h: 'قائمتك: التصفية والخريطة والقريب (Nearby)', b: 'قائمتك تعرض الأقسام التي لك فيها محتوى بعدّاداتها. صفِّ بالتصنيف ثم الفرعي. بدّل العرض: <b>☰ List · 🗺 Map</b>؛ و«📍 Nearby» (بجوار Day plan) يرتّب أماكن المدينة بالبعد المستقيم عن موضعك — ≤ 1 km · ≤ 3 km · Any — بزر <i>Go</i> يفتح تطبيق الملاحة الذي اخترته. موقعك يُطلب عند النقر ولا يُخزَّن.' } },
  { id: 'places.export', dest: 'places', tags: ['r116'], ui: ['Export', 'choose places', 'All', 'None', 'Continue', 'Send as image', 'Send as text', 'Choose places'],
    en: { h: 'Exporting part of a list', b: '<i>Export</i> opens with <i>choose places</i>: every place of the city under its category, each with a tick. Tick one place, or tick a category to take all of it; <i>All</i> and <i>None</i> do the whole city. If your list is filtered — by category, by search, or by a town — only what the filter shows starts ticked, so filtering first is the quick way to send one category. <i>Continue</i> shows the card for the ticked places; <i>Send as image</i> and <i>Send as text</i> both carry the same choice, and <i>Choose places</i> on the preview takes you back to change it. The choice lasts for that one export.' },
    ar: { h: 'تصدير جزء من القائمة', b: '<i>Export</i> يفتح أولًا <i>choose places</i>: كل أماكن المدينة تحت تصنيفاتها، ولكل مكان علامة. علّم مكانًا واحدًا، أو علّم التصنيف لتأخذه كله؛ و<i>All</i> و<i>None</i> للمدينة كلها. وإن كانت قائمتك مصفّاة — بتصنيف أو بحث أو بلدة — فما تُظهره التصفية وحده يبدأ معلَّمًا، فالتصفية أولًا أسرع طريق لإرسال تصنيف واحد. <i>Continue</i> يعرض البطاقة بالأماكن المعلَّمة؛ و<i>Send as image</i> و<i>Send as text</i> يحملان الاختيار نفسه، و<i>Choose places</i> في المعاينة يعيدك لتغييره. والاختيار لهذا التصدير وحده.' } },
  { id: 'places.add', dest: 'places', tags: ['r93'], ui: ['Google Maps link', 'Plus code', 'Fine dining', 'Top place', 'Outside the city'],
    en: { h: 'Adding a place', b: 'The window starts with the <b>Google Maps link</b> — paste what Maps shared (or tap 📋 Paste) and the name and area fill in; then <b>Plus code</b> (from under the address in Maps: one exact pin, and the area reads from it), then Name, then the category with <i>Fine dining · ⭐ Top place · Outside the city</i>.' },
    ar: { h: 'إضافة مكان', b: 'النافذة تبدأ بخانة <b>Google Maps link</b> — الصق ما شاركته الخرائط (أو اضغط 📋 Paste) فيُملأ الاسم والحي؛ ثم <b>Plus code</b> (من تحت العنوان في الخرائط: دبوس دقيق، والحي يُقرأ منه)، ثم الاسم، ثم التصنيف مع <i>Fine dining · ⭐ Top place · Outside the city</i>.' } },
  { id: 'places.outside', dest: 'places', tags: ['r97'], ui: ['Outside the city', 'Merge into another city', 'Split out a town', 'Undo'],
    en: { h: 'Outside the city and managing a city', b: '<b>Outside the city</b> marks a nearby town kept under this city; when a city has such towns, a row <b>Places outside …: Estepona · N</b> appears above the categories — tap a town to see its places only (list and map), tap it again for the whole city; the town chip on a card opens it too. <b>⚙</b> at the end of the row manages the city: <i>Merge into another city</i>, <i>Split out a town</i>, move one place from Edit, <i>🗑 beside a town</i> (removes that folded town and its places; the rest of the city stays), and <i>Undo</i>.' },
    ar: { h: 'خارج المدينة وإدارة المدينة (Outside the city)', b: '<b>Outside the city</b> يسِم بلدة مجاورة مضمومة تحت هذه المدينة؛ وحين يكون في المدينة بلدات يظهر صف <b>Places outside …: Estepona · N</b> فوق التصنيفات — اضغط البلدة لعرض أماكنها وحدها (قائمةً وخريطة)، واضغطها ثانيةً للمدينة كلها؛ وشريحة البلدة على البطاقة تفتحه أيضًا. <b>⚙</b> آخر الصف يدير المدينة: <i>Merge into another city</i> · <i>Split out a town</i> · نقل مكان واحد من Edit · <i>🗑 بجانب البلدة</i> (يحذف البلدة المضمومة بأماكنها وتبقى بقية المدينة) · <i>Undo</i>.' } },
  { id: 'places.dups', dest: 'places', tags: ['r97'], ui: ['Duplicates', 'Same Google place', 'Same spot', 'Keep this'],
    en: { h: 'Duplicates', b: 'Places you have twice show as a folded row <i>▸ Duplicates · N</i> in the box above the list — <i>Same Google place</i> or <i>Same spot</i>; tap a name to open its card, then <i>Keep this</i> on the one to keep (the rest merge into it; Undo sits on the row).' },
    ar: { h: 'المكرَّر', b: 'الأماكن التي لديك مرتين صفٌّ مطوي <i>▸ Duplicates · N</i> في الصندوق فوق القائمة — <i>Same Google place</i> أو <i>Same spot</i>؛ اضغط الاسم لفتح بطاقته ثم <i>Keep this</i> على ما تُبقيه (والبقية تُدمج فيه؛ وUndo على الصف).' } },
  { id: 'places.onespot', dest: 'places', tags: ['r96'], ui: ['Keep both', 'Keep mine', 'Replace mine', 'Drop this row'],
    en: { h: 'One spot, one place', b: 'Saving or pinning a place at a spot you already have asks <i>Keep both · Keep mine · Replace mine</i>; in a batch such rows are held with <i>Keep both · Drop this row</i>.' },
    ar: { h: 'موقع واحد مكان واحد', b: 'حفظ مكان أو تثبيته في موقع لديك أصلًا يسأل <i>Keep both · Keep mine · Replace mine</i>؛ وفي الدفعة تُحجز هذه الصفوف مع <i>Keep both · Drop this row</i>.' } },
  { id: 'places.areas', dest: 'places', tags: ['r96'], ui: [],
    en: { h: 'Areas', b: 'The area is read from the pin by one rule for every path (Paris → 7e arr. · Vienna → district · a village before its hamlet, the city or canton never); after this update a one-time <i>Re-read N pins</i> banner refreshes the areas you already have. With a town chip on, the box above the list (without a category / old category) shows that town only, and the chip says how many are in the box.' },
    ar: { h: 'الحي', b: 'يُقرأ من الدبوس بقاعدة واحدة لكل المسارات (باريس → 7e arr. · فيينا → المقاطعة · القرية قبل النجع، ولا المدينة ولا الكانتون أبدًا)؛ وبعد هذا التحديث يظهر مرة واحدة شريط <i>Re-read N pins</i> يحدّث أحياء ما لديك. ومع شريحة بلدة مفعّلة يعرض الصندوق فوق القائمة (بلا تصنيف / تصنيف قديم) تلك البلدة وحدها، والشريحة تقول كم منها في الصندوق.' } },
  { id: 'places.shortcode', dest: 'places', tags: ['r102-أ'], ui: ['8FR9+2V Interlaken'],
    en: { h: 'Short Plus codes', b: 'A short code (6 characters) is only exact near its town, so it is decoded around a reference: the town name Google copies with it (<b>8FR9+2V Interlaken</b>), else the town when the place is marked Outside the city, else this city. If the result lands more than 40 km from that reference nothing is saved and the message asks for the code with its town name or the full code; this catches a wrong reference only when both candidate spots are far, so for a far place always keep the town name with the code.' },
    ar: { h: 'الرمز القصير', b: 'الرمز القصير (ستة أحرف) لا يكون دقيقًا إلا قرب بلدته، لذلك يُفكّ حول مرجع: اسم البلدة الذي ينسخه Google مع الرمز (8FR9+2V Interlaken)، وإلا البلدة إن كان المكان موسومًا Outside the city، وإلا هذه المدينة. وإن وقع الناتج أبعد من ٤٠ كم عن مرجعه لا يُحفظ شيء وتطلب الرسالة الرمز مع اسم بلدته أو الرمز الكامل؛ هذا يصيد المرجع الخطأ حين يبعد المرشَّحان معًا فقط، فأبقِ اسم البلدة مع الرمز للمكان البعيد دائمًا.' } },
  { id: 'places.dayplans', dest: 'places', tags: ['r101-ب', 'r102-د', 'r103'], ui: ['· draft'],
    en: { h: 'Day plans in a city', b: 'When a city holds three places or more and no day plan yet, one line above My places offers to plan a day; it goes away with the first plan. Saved day plans of this city show as chips under the button row — 🏙 in the city, 🚞 day trip, <i>· draft</i> for an unfinished one — and open with one tap. <b>They follow the list</b>: when a city list is public, its day plans are public with it; when it is shared by name, they are shared with the same people — no switch to set. Viewers see them as chips on your city page and open them read-only: stops in order, category, note and distances; the app does not show them your start point, times or leg minutes (those fields still travel inside the plan document, as with any public trip). Drafts never leave you; a plan follows the list when you save it. Day plans never appear in the trips feeds, and deleting or merging a city makes its plans private again.' },
    ar: { h: 'خطط اليوم في المدينة', b: 'حين تملك المدينة ثلاثة أماكن فأكثر ولا خطة يوم فيها يظهر سطر واحد فوق My places يدعوك لتخطيط يوم، ويختفي بأول خطة. الخطط اليومية المحفوظة لهذه المدينة تظهر شرائح تحت صف الأزرار — 🏙 داخل المدينة · 🚞 رحلة يوم · <i>· draft</i> لغير المكتملة — وتفتح بضغطة. <b>وتتبع القائمة</b>: القائمة العامة خططها عامة معها، والمشارَكة بالاسم خططها مشارَكة مع الأشخاص أنفسهم — بلا مفتاح؛ المشاهد يراها شرائح في صفحة مدينتك ويفتحها للقراءة: المحطات بترتيبها والفرعي والملاحظة والمسافات؛ ولا يعرض له التطبيق نقطة انطلاقك ولا أوقاتك ولا دقائق الأرجل (هذه الحقول تبقى داخل مستند الخطة كأي رحلة عامة). المسودة لا تخرج أبدًا؛ الخطة تتبع القائمة عند حفظها. خطط اليوم لا تظهر في خلاصات الرحلات، وحذف المدينة أو دمجها يعيد خططها خاصة.' } },
  { id: 'places.visibility', dest: 'places', tags: ['r104'], ui: ['VIS', "Couldn't read this list's places", 'No active places'],
    en: { h: 'Public and shared, under the hood', b: "A city list is one index document plus one document per sub-category, and each of those carries its own public/shared mark, so a viewer can read only the sub-categories that carry it. Pressing 🌐 or sharing by name now stamps every sub-category in the same write, and opening your own list once repairs any sub-category whose mark fell out of step (Diagnostics shows a <i>VIS</i> line ending in “repaired”). A viewer who meets a list that claims places but shows none sees <i>Couldn't read this list's places</i> rather than <i>No active places</i>." },
    ar: { h: 'العام والمشارَك من الداخل', b: "قائمة المدينة مستند فهرس ومستند لكل فرعي، وكل فرعي يحمل علامة العام/المشارَك بنفسه، فلا يقرأ المشاهد إلا الفرعيات التي تحملها. ضغط 🌐 أو المشاركة بالاسم يختم الآن كل الفرعيات في الكتابة نفسها، وفتحك قائمتك مرة يصلح أي فرعي خرجت علامته عن الأم (يظهر في التشخيص سطر <i>VIS</i> ينتهي بـ«repaired»). والمشاهد الذي يفتح قائمة تقول إن فيها أماكن ولا يقرأ شيئًا يرى <i>Couldn't read this list's places</i> لا <i>No active places</i>." } },
  { id: 'places.pins', dest: 'places', tags: ['r107'], ui: ['City', 'Far pins'],
    en: { h: 'Names and pins', b: 'A short Plus code (PXCR+2C New York) is read around the town it names. The name is matched by its main name first — a side-name that only a far-away town carries is never trusted on its own: when the name is unclear you are asked <i>Which …?</i> or <i>Where is …?</i> instead of getting a pin in the wrong place. A pin that would land far from this city is not saved quietly either: <i>That pin is … km from …</i> lets you go back and fix it, or keep it as outside the city. <b>⚙ City › Far pins</b> lists pins saved far from the city that are not marked outside, shows where the same code lands near the city, and moves them (one or all, with Undo).' },
    ar: { h: 'الأسماء والدبابيس', b: 'الرمز القصير (PXCR+2C New York) يُقرأ حول البلدة التي يسمّيها. الاسم يُطابَق باسم المدينة الأصلي أولًا، والاسم الجانبي الذي لا تحمله إلا بلدة بعيدة لا يُصدَّق وحده: عند اللبس تُسأل <i>Which …?</i> أو <i>Where is …?</i> بدل دبوس في غير موضعه. والدبوس الذي سيقع بعيدًا عن المدينة لا يُحفظ صامتًا: <i>That pin is … km from …</i> تعيدك لتصحيحه أو تحفظه خارج المدينة. <b>⚙ City › Far pins</b> تعرض الدبابيس المحفوظة بعيدًا عن المدينة بلا وسم outside، وأين يقع الرمز نفسه قرب المدينة، وتنقلها (واحدًا أو الكل) مع تراجع.' } },
  { id: 'places.notvisible', dest: 'places', tags: ['r109'], ui: ['VIS'],
    en: { h: 'Not fully visible yet', b: 'A dot on 🌐 means some sub-categories of this list still carry a different public/shared mark than the list itself (a repair could not be written — offline, refused, or the account is suspended). Tap 🌐 and the app tries the repair again; it does not switch public on or off while the dot is there. Saving the whole list (or switching public / sharing) writes the mark on every sub-category and clears the dot too. Diagnostics shows one line for every visibility event: <i>VIS · city · public|private · shared N · what happened</i>.' },
    ar: { h: 'Not fully visible yet', b: 'نقطة على 🌐 تعني أن بعض تصنيفات القائمة ما زالت تحمل علم عام/مشارَك يخالف القائمة نفسها (إصلاح لم يُكتب: بلا اتصال، أو رُفض، أو الحساب موقوف). اضغط 🌐 فيعيد التطبيق محاولة الإصلاح، ولا يبدّل العام ما دامت النقطة. وحفظ القائمة كاملة (أو تبديل العام أو المشاركة) يكتب العلم على كل تصنيف فيطفئ النقطة أيضًا. وفي التشخيص سطر واحد لكل حدث رؤية: <i>VIS · city · public|private · shared N · ما حدث</i>.' } },
  { id: 'trips.build', dest: 'trips', tags: [], ui: ['No day yet', 'Move'],
    en: { h: 'Build a trip', b: 'Build a trip in two steps: the city, the days and the places you pick — optionally arrival, departure, where you stay and what you take when it is too far to walk — then MyPickz drafts each day in four periods: morning, noon, afternoon, evening, with alternatives when several places are of the same kind and a <i>No day yet</i> tray for what did not fit. <i>Move</i> anything, switch between Calm, Balanced and Dense, undo, then approve.' },
    ar: { h: 'ابنِ رحلة', b: 'ابنِ الرحلة بخطوتين: المدينة والأيام والأماكن التي تختارها — واختياريًّا الوصول والمغادرة ومكان الإقامة وما تركبه حين يبعد المكان عن المشي — ثم يرسم MyPickz كل يوم بأربع فترات: صباح · ظهيرة · عصر · مساء، مع بدائل حين تتعدد أماكن الصنف نفسه، وصينية <i>No day yet</i> لما لم يتسع له البرنامج. انقل ما شئت بـ<i>Move</i>، وبدّل بين Calm وBalanced وDense، وتراجع، ثم اعتمد.' } },
  { id: 'trips.arrange', dest: 'trips', tags: ['r105'], ui: ['Arrange it myself', 'Auto-fill the rest', 'Add again…', 'Trip'],
    en: { h: 'Arrange and reorder', b: "Prefer to place them yourself? <i>Arrange it myself</i> keeps every place in the tray and the grid asks you for each one in turn; <i>Auto-fill the rest</i> places what is left. The ▲ ▼ arrows in a stop's row of actions reorder it within its period; moving into another period that already has stops asks where in the order; <i>Add again…</i> adds a second visit to the same place (the same name in both paths). Tap <i>Trip</i> on any place card and it lands in its best slot — or in the tray." },
    ar: { h: 'الترتيب بنفسك', b: 'تفضّل الترتيب بنفسك؟ «Arrange it myself» يبقي كل الأماكن في الصينية وتسألك الشبكة عن كلٍّ بدوره، و«Auto-fill the rest» يضع ما بقي. السهمان ▲ ▼ في صف أفعال المحطة يرتّبانها داخل فترتها؛ وحين تنقل إلى فترة أخرى فيها محطات تختار موضعه في الترتيب؛ و«Add again…» يضيف زيارة ثانية للمكان نفسه (الاسم نفسه في المسارين). اضغط <i>Trip</i> على أي بطاقة مكان فيهبط في خانته الأنسب — أو في الصينية.' } },
  { id: 'trips.route', dest: 'trips', tags: [], ui: ['Navigate', 'est.', 'Incomplete'],
    en: { h: 'Day route', b: 'Open an approved trip, pick a day, set when you leave and by when you want to be back; each leg shows its rough distance and a mode (walk, metro and transit, car — the default follows the distance), and <i>Navigate</i> opens your app in that mode. Each leg starts from an estimate (≈ with <i>est.</i> — from its distance and mode; rough, and rougher in mountains and across water). Write the minutes your app shows and they replace it; ↺ returns to the estimate. The day shows <i>Incomplete</i> only when a leg has neither a distance (an unpinned place) nor minutes.' },
    ar: { h: 'مسار اليوم', b: 'افتح رحلة معتمدة واختر يومًا وحدّد متى تخرج ومتى تريد العودة؛ كل رِجل تعرض مسافتها التقريبية ووسيلتها (مشي · مترو ومواصلات · سيارة — الافتراض من المسافة)، و<i>Navigate</i> يفتح تطبيقك بالوضع نفسه. كل رِجل تبدأ بتقدير (≈ ومعه <i>est.</i> — من مسافتها ووسيلتها؛ تقريبي، ويبتعد أكثر في الجبال وعبر الماء). اكتب الدقائق التي يعرضها تطبيقك فتحلّ محله، و↺ يعيد التقدير. يظهر على اليوم <i>Incomplete</i> فقط حين تكون رِجل بلا مسافة (مكان غير مثبَّت) وبلا دقائق.' } },
  { id: 'trips.end', dest: 'trips', tags: ['r110'], ui: ['＋ End point', 'Back to start', 'Another point', 'No end point', 'Back by'],
    en: { h: 'Where the day ends', b: 'Nothing is assumed about where the day ends: <i>＋ End point</i> at the end of the route offers <i>Back to start</i>, <i>Another point</i> (a name, with a Plus code or a Google Maps link for its distance) or <i>No end point</i>; a return after <i>Back by</i> is flagged.' },
    ar: { h: 'نهاية اليوم', b: 'لا يُفترض شيء عن نهاية اليوم: صف <i>＋ End point</i> في آخر المسار يعرض <i>Back to start</i> أو <i>Another point</i> (اسم، ومعه رمز Plus أو رابط خرائط لمسافته) أو <i>No end point</i>؛ والعودة بعد <i>Back by</i> تُعلَّم.' } },
  { id: 'trips.dayplan', dest: 'trips', tags: ['r106'], ui: ['In the city', 'My order', 'Day trip', 'Nearest first'],
    en: { h: 'Day plan — one path, one difference', b: 'A one-day plan that lives in Places, not in My trips. The two paths share everything — the two doors that add stops, Start from and the end point you choose, Options, Add again, the leg modes, the place card, the same Day route after saving — and differ in one thing you choose on the first screen: <b>who orders the stops</b>. <b>In the city</b>: MyPickz by periods (morning, midday, afternoon, evening, with Options when two places are of the same kind) or <i>My order</i>. <b>Day trip</b>: <i>My order</i> (the order you add them in, ▲ ▼) or <i>Nearest first</i> from your start point (each added stop slots in nearest-first; move one by hand and the order is yours again).' },
    ar: { h: 'خطة اليوم — مسار واحد بفرق واحد', b: 'خطة يوم واحد تعيش في الأماكن لا في My trips. المساران يشتركان في كل شيء — بابا إضافة المحطات، Start from ونقطة النهاية التي تختارها، Options، Add again، وسائل الأرجل، بطاقة المكان، وDay route نفسه بعد الحفظ — ويختلفان في شيء واحد تختاره في الشاشة الأولى: <b>من يرتّب المحطات</b>. <b>In the city</b>: MyPickz بالفترات (صباح · ظهر · عصر · مساء، مع Options حين يتشابه مكانان) أو <i>My order</i>. <b>Day trip</b>: <i>My order</i> (ترتيب إضافتك، ▲ ▼) أو <i>Nearest first</i> من نقطة الانطلاق (كل محطة تُضاف تحطّ في أقرب موضع؛ حرّك واحدة بيدك فيعود الترتيب لك).' } },
  { id: 'trips.kinds', dest: 'trips', tags: ['r101-ب'], ui: ['In the city', 'Day trip', '＋ Add places', 'A place not in My places'],
    en: { h: 'In the city and Day trip, in detail', b: 'Two kinds, in detail — <b>In the city</b> (your places in the usual rhythm) and <b>Day trip</b> (a linear route out of the city: villages, peaks, lakes, stations — stops come in through <i>＋ Add places</i>: your saved places here and nearby, shown with their category and note, or <i>A place not in My places</i> inside it (typed, or from a Maps link — it stays inside this plan); each leg with its transport: train, boat, cable car, cogwheel, bus, walk, car — notes, an optional stop, a fixed time; nothing is written until you save).' },
    ar: { h: 'النوعان بالتفصيل (In the city · Day trip)', b: 'النوعان بالتفصيل — <b>In the city</b> (أماكنك بالإيقاع المعتاد) و<b>Day trip</b> (مسار خطّي خارج المدينة: قرى · قمم · بحيرات · محطات — تدخل المحطات من <i>＋ Add places</i>: أماكنك المحفوظة هنا وفي المدن القريبة بفرعيّها وملاحظتها، أو <i>A place not in My places</i> من داخله (تكتبه أو من رابط خرائط — يبقى داخل هذه الخطة)؛ ولكل رِجل وسيلتها: قطار · مركب · تلفريك · قطار جبلي · باص · مشي · سيارة — وملاحظة، ومحطة اختيارية، ووقت مثبَّت؛ ولا يُكتب شيء حتى تحفظ).' } },
  { id: 'trips.staytransport', dest: 'trips', tags: ['r102-ب'], ui: ['Stay', 'Transportation'],
    en: { h: 'Stay and Transportation as stops', b: 'In the picker, <b>Stay</b> and <b>Transportation</b> places are pickable like any other (a resort with a café or golf, a station, a car park: 60 and 15 minutes by default).' },
    ar: { h: 'الإقامة والتنقل محطاتٍ (Stay · Transportation)', b: 'في المنتقي أماكن <b>Stay</b> و<b>Transportation</b> تُختار كغيرها (منتجع فيه مقهى أو غولف، محطة، موقف: ٦٠ و١٥ دقيقة افتراضًا).' } },
  { id: 'trips.saved', dest: 'trips', tags: ['r102-ج'], ui: ['Trip name', 'Day plan ▸ Saved', '⧉ Copy into a trip'],
    en: { h: 'A saved day plan: open, name, copy', b: "In a saved plan, tapping a stop's name opens its place card — category, area, note, Google Maps — and the line under the name shows category and area; a stop's pin follows the place's current pin in your list, so correcting a pin corrects the distances. Give it a <b>Trip name</b>; open it from <i>Day plan ▸ Saved</i> or from its chip in Places; <b>⧉ Copy into a trip</b> copies the day into one of your trips as a new day or in place of one, with Undo." },
    ar: { h: 'الخطة المحفوظة: فتحها وتسميتها ونسخها', b: 'في الخطة المحفوظة الضغط على اسم المحطة يفتح بطاقة المكان — الفرعي والحي والملاحظة وGoogle Maps — والسطر تحت الاسم يعرض الفرعي والحي؛ ودبوس المحطة يتبع دبوس المكان الحالي في قائمتك فيصحّح تصحيحُه المسافات. سمِّها بـ<b>Trip name</b>، وافتحها من <i>Day plan ▸ Saved</i> أو من شريحتها في Places، و<b>⧉ Copy into a trip</b> ينسخ اليوم إلى إحدى رحلاتك يومًا جديدًا أو بدل يوم، مع Undo.' } },
  { id: 'trips.nearby', dest: 'trips', tags: ['r101-أ'], ui: ['Gstaad'],
    en: { h: 'Nearby cities', b: 'When you pick from My places, a row of chips names your other cities within about an hour and a half by car one way — <i>+ Gstaad · ~1 h</i>; tap one and its places join the list under its name, and each picked place keeps the city it belongs to. The time is an estimate from the straight-line distance, not a route.' },
    ar: { h: 'المدن القريبة', b: 'حين تختار من My places يظهر صف شرائح بمدنك الأخرى التي تبعد نحو ساعة ونصف قيادة في اتجاه واحد أو أقل — «+ Gstaad · ~1 h»؛ اضغط إحداها فتنضم أماكنها إلى القائمة تحت اسمها، ويحتفظ كل مكان مختار بمدينته. الزمن تقدير من المسافة المستقيمة لا من طريق فعلي.' } },
  { id: 'trips.both', dest: 'trips', tags: ['r105', 'r110'], ui: ['A place not in My places', '＋ Add places', 'No day yet'],
    en: { h: 'In both paths', b: "Start from in a day plan lists Transportation first (station, parking), then Stay, then the rest of your pinned places, and an unpinned place is listed greyed with the reason (the multi-day Where you stay picker greys them too). Options in Day route after saving: a stop with alternatives shows Option 1 ✓ and Option 2… — tap one to make it the real stop; the legs are recomputed for it, but minutes you typed for the old option are not carried, so re-enter them. Add again: the same place once more — on every stop row in both paths: in the city it asks the day and period, in a day trip it adds a copy at the end of the route. The row actions come in one order in both paths: ▲ ▼ · Move · ✎ Edit or ⚠ Alert · optional · Add again · ✕. In the city, a typed stop (<i>A place not in My places</i> inside <i>＋ Add places</i>) lands in <i>No day yet</i> and the Move sheet asks where. Viewers of a public or shared day plan see each leg in the mode you chose, with its note, and open the place card from a stop's name." },
    ar: { h: 'في المسارين', b: 'مكان ليس في My places يُضاف داخل مدينة خطة اليوم من <i>A place not in My places</i> داخل <i>＋ Add places</i> فيحطّ في <i>No day yet</i> وتسأله ورقة Move عن موضعه · Options في Day route بعد الحفظ: المحطة التي لها بدائل تعرض Option 1 ✓ وOption 2…، والضغط يجعل البديل المحطة الفعلية وتُحسب الأرجل عليه، لكن الدقائق التي كتبتها للخيار القديم لا تنتقل فأعد إدخالها · Add again: المكان نفسه مرة أخرى — على كل صف محطة في المسارين: داخل المدينة يسأل اليوم والفترة، وفي رحلة اليوم يضيف نسخة في آخر المسار. وأفعال الصف بترتيب واحد في المسارين: ▲ ▼ · Move · ✎ Edit أو ⚠ Alert · optional · Add again · ✕ · Start from في خطة اليوم: النقل أولًا ثم الإقامة ثم البقية، وغير المثبَّت معطَّل بسببه (وفي «Where you stay» للرحلة متعددة الأيام كذلك) · المشاهد يرى وسيلة كل رِجل كما اخترتها مع ملاحظتها ويفتح بطاقة المكان من اسم المحطة.' } },
  { id: 'trips.shapes', dest: 'trips', tags: ['r107'], ui: ['your order', 'Trip', 'Move', 'Make it an in-city day', 'Add again', 'Kept as it was'],
    en: { h: 'Two day shapes', b: "An in-city day is laid out in periods; a day-trip day keeps its stops in <i>your order</i>. Every step now knows both: Setup and Done keeps a day trip's stops, start point and order; <i>Trip</i> on a place card adds it as the last stop of a day trip and says so; a day plan copied into a longer trip keeps its day when you change days or rhythm, opens with the same stop editor (day chips on top, <i>Move</i> on each stop), and the Move sheet shows it as one wide cell — the place joins its route. An emptied day-trip day can be turned back with <i>Make it an in-city day</i>. Copies made with <i>Add again</i> and your alerts survive a rebuild. If a step would ever drop a place or redraw such a day without asking, nothing is saved, the plan returns as you last saved it and a sheet says <i>Kept as it was</i>." },
    ar: { h: 'شكلان لليوم', b: 'يوم داخل المدينة بفتراته، ويوم رحلة اليوم بمحطاته على <i>your order</i>. كل خطوة تعرف الشكلين: Setup ثم Done يُبقي محطات رحلة اليوم ونقطة انطلاقها وترتيبها · <i>Trip</i> على بطاقة مكان يضيفه آخر محطة في رحلة اليوم ويقول ذلك · خطة اليوم المنسوخة إلى رحلة أطول تحتفظ بيومها عند تغيير الأيام أو الإيقاع وتُفتح بمحرّر المحطات نفسه (شرائح الأيام أعلاه وMove على كل محطة)، وورقة النقل تعرضها خلية واحدة عريضة · اليوم الذي أُفرغ يعود بـ<i>Make it an in-city day</i> · نسخ <i>Add again</i> وتنبيهاتك تبقى بعد إعادة البناء. وإن كادت خطوة تُسقط مكانًا أو تعيد رسم يوم بلا سؤال فلا يُحفظ شيء، وتعود الخطة كما حفظتها آخر مرة، وتظهر ورقة <i>Kept as it was</i>.' } },
  { id: 'trips.session', dest: 'trips', tags: ['r108', 'r110'], ui: ['Cancel', 'Save as draft', 'Approve', 'Done', 'Discard your changes?', 'Restore your unsaved edit?'],
    en: { h: 'Editing is a session', b: 'Nothing is written while you edit. A plan that is not approved yet ends with <i>Cancel · Save as draft · Approve</i> (<i>Save as draft</i> writes and keeps you in the editor); an approved one with <i>Cancel · Done</i>. Leaving with changes asks <i>Discard your changes?</i> and, if you discard, the plan is exactly as it was. If the app closes in the middle, your edit is kept on this device only and the next visit asks <i>Restore your unsaved edit?</i>.' },
    ar: { h: 'التحرير جلسة', b: 'لا شيء يُكتب وأنت تحرّر. الخطة التي لم تُعتمد بعد تنتهي بـ<i>Cancel · Save as draft · Approve</i> (و<i>Save as draft</i> يحفظ ويُبقيك في المحرّر)، والمعتمدة بـ<i>Cancel · Done</i>. الخروج بتعديلات يسأل <i>Discard your changes?</i> وإن تخلّيت عادت الخطة كما كانت تمامًا. وإن أُغلق التطبيق في المنتصف بقي تحريرك على هذا الجهاز وحده، ويسألك عند الزيارة التالية <i>Restore your unsaved edit?</i>.' } },
  { id: 'trips.adddoor', dest: 'trips', tags: ['r110'], ui: ['＋ Add places', 'A place not in My places', 'No day yet', 'Setup', 'Pick places', '✏️ Edit'],
    en: { h: 'One door to add places', b: 'There is one door to add: <i>＋ Add places</i> — tick places in My places and nearby cities, or open <i>A place not in My places</i> inside it — and a note then says where each one landed (the period, an alternative, the stop number, or <i>No day yet</i>). It sits in the same two spots in both paths: the first chip at the top of the editor and a wide door under the last stop; <i>Setup</i> has the same <i>Pick places</i> door for both (in a day trip what you tick becomes stops in the order you tick it — or nearest-first when that order is on), and <i>＋ Add places</i> next to <i>✏️ Edit</i> on a saved plan opens the editor with the same picker.' },
    ar: { h: 'باب واحد للإضافة', b: 'للإضافة باب واحد: <i>＋ Add places</i> — علّم أماكن من My places والمدن القريبة، أو افتح <i>A place not in My places</i> من داخله — ثم يقول إشعار أين حلّ كل مكان (الفترة، أو بديل، أو رقم المحطة، أو <i>No day yet</i>). وهو في الموضعين نفسيهما في المسارين: أول شريحة أعلى المحرّر وباب عريض تحت آخر محطة؛ وفي <i>Setup</i> باب <i>Pick places</i> نفسه للمسارين (وفي رحلة اليوم ما تؤشّره يصير محطات بترتيب تأشيرك — أو الأقرب فالأقرب حين يكون ذلك الترتيب مفعَّلًا)، و<i>＋ Add places</i> بجوار <i>✏️ Edit</i> في الخطة المحفوظة يفتح المحرّر والمنتقي نفسه.' } },
  { id: 'trips.setup', dest: 'trips', tags: [], ui: ['Setup', 'Apply', '✏️ Edit', '＋ Add places', 'Not saved', 'Trip'],
    en: { h: 'Setup, the guard and what stays immediate', b: '<i>Setup</i> is a step inside the session (<i>Apply</i> brings you back to the plan), and on a saved trip the setup, adding and arranging happen in the editing session: <i>✏️ Edit</i> opens it, and <i>＋ Add places</i> opens it with the picker already open. Inside a session the guard does not throw your work away: a save that would drop a place you did not remove is refused with <i>Not saved</i> and the edit stays open. Things done outside the editor stay immediate: <i>Trip</i> on a place card, copying a day plan, and Undo of the last of these.' },
    ar: { h: 'الإعداد والحارس وما يبقى فوريًّا (Setup)', b: '<i>Setup</i> خطوة داخل الجلسة (<i>Apply</i> يعيدك إلى الخطة)، والرحلة المحفوظة إعدادها وإضافة أماكنها وترتيبها في جلسة التحرير: <i>✏️ Edit</i> يفتحها، و<i>＋ Add places</i> يفتحها والمنتقي مفتوح. والحارس داخل الجلسة لا يضيّع عملك: الحفظ الذي كان سيُسقط مكانًا لم تحذفه يُرفض بورقة <i>Not saved</i> ويبقى التحرير مفتوحًا. وما تفعله خارج المحرّر يبقى فوريًّا: <i>Trip</i> على بطاقة المكان، ونسخ خطة يوم، والتراجع عن آخرها.' } },
  { id: 'curators.world', dest: 'curators', tags: [], ui: ['Top places', 'Best time of year', 'What I love', 'Known for', 'Why I prefer it', 'I return', 'Latest update places'],
    en: { h: 'A curator’s world', b: "A curator's world is a showcase of their favorites, on top of their ordinary lists: their <i>Top places</i>, their cities — each with a city card they keep updating in their own lines: <i>Best time of year</i>, <i>What I love</i>, <i>Known for</i>, <i>Why I prefer it</i>, <i>I return</i> — their trips, and <i>Latest update places</i>. Follow a curator to see what's new from them first. Browse their places and trips as they see them — read-only. Curators are invited by MyPickz or apply from their account; the badge means a space, not a rating." },
    ar: { h: 'عالم المنتقي', b: 'عالم المنتقي مساحة عرض لمفضلاته فوق قوائمه العادية: <i>Top places</i>، ومدنه — ولكل مدينة بطاقة يحدّثها بسطوره: <i>Best time of year</i> · <i>What I love</i> · <i>Known for</i> · <i>Why I prefer it</i> · <i>I return</i> — ورحلاته، و<i>Latest update places</i>. تابع منتقيًا ليصلك جديده أولًا. تصفّح أماكنه ورحلاته كما يراها — للعرض فقط. المنتقون يُدعون من MyPickz أو يطلبون من حسابهم؛ الشارة مساحة لا تقييم.' } },
  { id: 'community.browse', dest: 'community', tags: [], ui: [],
    en: { h: 'Public lists and trips', b: "Other users' public lists and trips, by city — and who saved what. Filter by category and sub-category; open a list and save a place to your own — it keeps its source. Your list is private until you make it public; sharing by name with one person stays between you two." },
    ar: { h: 'القوائم والرحلات العامة', b: 'قوائم المستخدمين الآخرين ورحلاتهم العامة بالمدينة — ومن حفظ ماذا. صفِّ بالتصنيف والفرعي؛ افتح قائمة واحفظ مكانًا إلى قائمتك — يحتفظ بمصدره. قائمتك خاصة حتى تجعلها عامة؛ والمشاركة بالاسم مع شخص تبقى بينكما.' } },
  { id: 'community.popular', dest: 'community', tags: ['r116'], ui: ['Popular in', 'saved by', 'Not enough saves in this city yet'],
    en: { h: 'Popular in a city', b: 'Pick a city in Community and a box opens above its lists: <i>Popular in</i> Lisbon — the places people saved most from public lists there, all-time (counted from the day this feature arrived), most saved first. Each person counts once per place, and removing your saved copy takes your count back. Each is a full place card: open it in Google Maps, save it to your list with credit to the list it came from, add it to a trip. The same box sits folded under your own list of that city in Places; tap its title to open it. A place card from someone else’s list in that city carries <i>saved by</i> and a number — how many people saved that place from a public list. It counts how many, never who. A place counts once per person, only when saved from a public list, and only in a city from the cities list (a city you typed yourself has no box). Until a place has been saved by at least two people the box says <i>Not enough saves in this city yet</i>.' },
    ar: { h: 'الرائج في المدينة', b: 'اختر مدينة في Community فيفتح صندوق فوق قوائمها: <i>Popular in</i> Lisbon — أكثر الأماكن التي حفظها الناس من القوائم العامة هناك، منذ البداية (يبدأ العدّ من يوم وصول هذه الميزة)، والأكثر حفظًا أولًا. كل شخص يُعدّ مرة للمكان، وحذف نسختك المحفوظة يعيد عدّك. كل واحد بطاقة مكان كاملة: افتحه في خرائط جوجل، احفظه إلى قائمتك بإسناد إلى القائمة التي جاء منها، أضفه إلى رحلة. والصندوق نفسه مطويّ تحت قائمتك لتلك المدينة في Places؛ اضغط عنوانه لفتحه. وبطاقة المكان من قائمة غيرك في تلك المدينة تحمل <i>saved by</i> ورقمًا — كم شخصًا حفظ ذلك المكان من قائمة عامة. يُعدّ الكم لا مَن. المكان يُعدّ مرة لكل شخص، وحين يُحفظ من قائمة عامة فقط، وفي مدينة من قائمة المدن فقط (مدينة كتبتها بنفسك لا صندوق لها). وإلى أن يحفظ المكانَ شخصان على الأقل يقول الصندوق <i>Not enough saves in this city yet</i>.' } },
  { id: 'community.mystats', dest: 'community', tags: ['r116'], ui: ['My stats', 'My summary', 'Count pinned and saved-from places', 'Impact rate', 'Places people opened · save growth', 'Save growth'],
    en: { h: 'My stats: your summary and your lists’ impact', b: '<i>My stats</i> (in the ☰ menu) opens with <i>My summary</i>: how many places, cities and trips you have — at once, from what the screen already reads. <i>Count pinned and saved-from places</i> reads each city once and adds how many of your places have a pin, how many do not yet, and how many you saved from someone else’s list. Each public list then shows its impact: views, bookmarks and saves, where it was opened from, how many arrived by scanning its share card, and an <i>Impact rate</i> — saves out of views — once it has enough views to mean something. <i>Places people opened · save growth</i> opens the detail: <i>Save growth</i> over the last 14 days, and the places people opened in Maps or added to a trip most. Private lists are not counted. These are numbers only — never who.' },
    ar: { h: 'My stats: حصيلتك وأثر قوائمك', b: '<i>My stats</i> (في قائمة ☰) يبدأ بـ<i>My summary</i>: كم مكانًا ومدينة ورحلة لديك — فورًا، ممّا تقرؤه الشاشة أصلًا. و<i>Count pinned and saved-from places</i> يقرأ كل مدينة مرة ويضيف كم مكانًا له دبوس، وكم بلا دبوس بعد، وكم حفظتَه من قائمة غيرك. ثم كل قائمة عامة بأثرها: المشاهدات والمفكرات والحفظ، ومن أين فُتحت، وكم وصل بمسح بطاقتها، و<i>Impact rate</i> — الحفظ من المشاهدات — حين تبلغ مشاهداتها ما يجعل النسبة ذات معنى. و<i>Places people opened · save growth</i> يفتح التفصيل: <i>Save growth</i> لآخر ١٤ يومًا، والأماكن الأكثر فتحًا في الخرائط أو دخولًا للرحلات. القوائم الخاصة لا تُعدّ. وهذه أرقام فقط — بلا أسماء.' } },
  { id: 'community.reads', dest: 'community', tags: ['r109'], ui: [],
    en: { h: 'When the market is read', b: "The market is read once and kept for the visit — going back, changing tab or returning within ten minutes reads nothing; the line under the filters says when it was read, and ↻ reads it again now. What you do yourself — publish or hide, bookmark, save, copy — is read from the server right after, so your own change never waits; view counts and other people's changes arrive with the next read." },
    ar: { h: 'متى يُقرأ السوق', b: 'السوق يُقرأ مرة ويبقى للزيارة — العودة وتبديل التبويب والرجوع خلال عشر دقائق بلا قراءة؛ السطر تحت المرشّحات يقول متى قُرئ، و↻ يقرؤه الآن. وما تفعله أنت — نشر أو إخفاء، تمييز، حفظ، نسخ — يُقرأ من الخادم بعده مباشرة فلا ينتظر تغييرك؛ أما عدّاد المشاهدات وتغييرات الآخرين فتصل مع القراءة التالية.' } },
  { id: 'community.checked', dest: 'community', tags: ['r109'], ui: ['This list is no longer available'],
    en: { h: 'Checked when opened', b: 'A trip or a list kept in memory is checked with one read every time you open it — if its owner made it private, stopped sharing it, or the account was suspended, it is gone at once (<i>This list is no longer available</i>). Suspending an account hides every list, every sub-category under it and every trip; lifting it brings each one back exactly as it was.' },
    ar: { h: 'تحقق عند الفتح', b: 'الرحلة أو القائمة المحفوظة في الذاكرة تُتحقق بقراءة واحدة كلما فتحتها — إن جعلها صاحبها خاصة أو ألغى مشاركتها أو أُوقف حسابه اختفت فورًا (<i>This list is no longer available</i>). وإيقاف الحساب يُخفي كل قائمة وكل تصنيف تحتها وكل رحلة، ورفعه يعيد كل واحدة كما كانت.' } },
  { id: 'addresses.book', dest: 'addresses', tags: [], ui: [],
    en: { h: 'Your private book', b: 'Home, work, family, friends, clinics — your private book. Only you read it; nothing here ever appears in lists, trips, or the community. Paste from Maps, or type an address.' },
    ar: { h: 'دفترك الخاص', b: 'البيت والعمل والأهل والأصدقاء والعيادات — دفترك الخاص. أنت وحدك تقرأه؛ لا شيء منه يظهر بالقوائم أو الرحلات أو المجتمع. الصق من الخرائط أو اكتب عنوانًا.' } },
  { id: 'cards.export', dest: 'cards', tags: ['r116'], ui: ['Scan to open in MyPickz'],
    en: { h: 'Cards & sharing', b: "Any place, list, trip, or curator card can be exported as an image in the app's style — Arabic or English — with a QR code beside each place that opens it in Google Maps. The card of a public list or a public trip also carries one larger code in its footer — <i>Scan to open in MyPickz</i> — that opens that list or trip in the app; its owner sees how many arrived through it in My stats (a number, never who). A private list or trip has no footer code. Long lists split into several cards. Send it anywhere." },
    ar: { h: 'البطاقات والمشاركة', b: 'أي مكان أو قائمة أو رحلة أو بطاقة منتقٍ تُصدَّر صورةً بهوية التطبيق — عربية أو إنجليزية — برمز QR بجانب كل مكان يفتحه في خرائط جوجل. وبطاقة القائمة العامة أو الرحلة العامة تحمل أيضًا رمزًا أكبر في تذييلها — <i>Scan to open in MyPickz</i> — يفتح تلك القائمة أو الرحلة في التطبيق؛ وصاحبها يرى في My stats كم وصل عبره (رقمًا لا أسماء). القائمة أو الرحلة الخاصة بلا رمز تذييل. القوائم الطويلة تنقسم بطاقات. أرسلها حيث شئت.' } },
  { id: 'import.file', dest: 'import', tags: [], ui: ['takeout.google.com', 'Deselect all', 'Saved', 'Maps (your places)', 'Next step', 'Create export', 'Download your files'],
    en: { h: 'Get your file from Google', b: '1. Open <b>takeout.google.com</b>, sign in with the Google account you use in Maps → <i>Deselect all</i> → tick <b>two</b> items: <b>Saved</b> (your lists) and <b>Maps (your places)</b> → <i>Next step</i> → <i>Create export</i>.<br>2. Google emails you “Your Google data is ready” (minutes, up to a few hours) → <i>Download your files</i> → the .zip lands in Files → Downloads (iPhone) or Downloads (Android).<br>3. Here: ☰ → Import → choose the .zip (no need to unzip).' },
    ar: { h: 'ملفك من جوجل', b: '١. افتح <b>takeout.google.com</b> بحساب جوجل الذي تستعمله في الخرائط ← <i>Deselect all</i> ← اختر <b>بندين</b>: <b>Saved</b> (قوائمك) و<b>Maps (your places)</b> ← <i>Next step</i> ← <i>Create export</i>.<br>٢. يرسل لك جوجل بريد «Your Google data is ready» (دقائق إلى ساعات) ← <i>Download your files</i> ← يُحفظ الملف المضغوط في Files ← Downloads (iPhone) أو Downloads (Android).<br>٣. هنا: ☰ ← Import ← اختر الملف المضغوط (لا حاجة لفكّه).' } },
  { id: 'import.cities', dest: 'import', tags: [], ui: [],
    en: { h: 'Sorting into cities', b: '4. Your places are sorted into cities <b>on your device</b> — nothing is uploaded, nothing is read from Google. You see them as a tree: country → city → smaller towns, and decide with one tap whether a small town stays its own city or goes under the big city next door (as its area). A new city with only 1–2 places is tucked under the city next door by default when it is within 20 km (the row says so, with undo), or left unticked for you to decide; towns you saved as places (“Bled”, “Biarritz”) are counted as destinations and not imported unless you say so. Tell us once what each list is mostly about (optional).' },
    ar: { h: 'الفرز على المدن', b: '٤. تُفرز أماكنك على المدن <b>في جهازك</b> — لا يُرفع شيء ولا يُقرأ شيء من جوجل. تراها شجرةً: دولة ← مدينة ← بلدات أصغر، وتقرر بضغطة أتبقى البلدة الصغيرة مدينةً بذاتها أم تدخل تحت المدينة الكبيرة المجاورة (حيًّا فيها). المدينة الجديدة بمكان أو مكانين تُضمّ افتراضيًّا تحت المدينة المجاورة إن كانت ضمن ٢٠ كم (الصف يقولها مع undo)، وإلا تُترك بلا ✓ لقرارك؛ والبلدة التي حفظتها كمكان («Bled» · «Biarritz») تُعدّ وجهةً ولا تُستورد إلا بطلبك. أخبرنا مرة عمّا تدور حوله كل قائمة (اختياري).' } },
  { id: 'import.pin', dest: 'import', tags: ['r98b'], ui: ['not pinned yet', '✓ Suggested pins', 'Strong', 'Likely', '≈ Look-alikes', 'Pin from Google Maps', 'Pin', 'Plus code', 'GV74+C3 London', 'Paste', 'Not pinned yet'],
    en: { h: 'Pinning in three steps', b: '5. Open a city → the box above the list shows <b>N not pinned yet ›</b> until every place has a pin (the two status lines are gone — the file count lives in ⓘ Diag): everything from your file is on your list with its Google link; a pin is needed only to put a place in a day plan or see it on your map. MyPickz looks each place up in our map data (by name — even when your list link points a few km away) and sorts it into its category. Then three doors: <b>✓ Suggested pins</b> — one tap for <b>Strong</b> (exact name) and <b>Likely</b> (check the ↔ names; 🗑 anything old or unimportant, with Undo). <b>≈ Look-alikes</b> — for a place with look-alikes, tap the right one (each shows its address). <b>Pin from Google Maps</b> — for the rest, tap <b>Pin</b> on the card: open the place in Google Maps, swipe its card up and under the address tap <b>Plus code</b> (something like <b>GV74+C3 London</b> — it says Copied), come back and tap <b>Paste</b>: one exact pin, decoded on your device, no Google call. Every pinned card shows its own Plus code under the address, so checking a pin is comparing two lines — same code, same spot. Or keep them on your list without a pin (<b>Not pinned yet</b> lists them and can save them as a file). What it can’t tell stays in the box for you — including places outside the content guidelines (bars, nightlife, alcohol, hookah, gambling), which are marked and never sorted.' },
    ar: { h: 'التثبيت بثلاث خطوات', b: '٥. افتح مدينة ← الصندوق فوق القائمة يعرض <b>N not pinned yet ›</b> حتى يُثبَّت كل مكان (سطرا الحالة زالا — عدد الملف في ⓘ Diag): كل ما في ملفك صار في قائمتك برابطه في Google؛ والدبوس يلزم فقط لوضع المكان في مسار يوم أو رؤيته على خريطتك. يبحث MyPickz عن كل مكان في بيانات خرائطنا (بالاسم — حتى لو كان رابط قائمتك يشير إلى بُعد كيلومترات) ويفرزه إلى تصنيفه. ثم ثلاثة أبواب: <b>✓ Suggested pins</b> — ضغطة واحدة لـ<b>Strong</b> (اسم تامّ) و<b>Likely</b> (راجع الاسمين ↔؛ 🗑 على القديم أو غير المهم، مع Undo). <b>≈ Look-alikes</b> — للمكان ذي الأشباه اضغط الاسم الصحيح (كلٌّ بعنوانه). <b>Pin from Google Maps</b> — للباقي اضغط <b>Pin</b> على البطاقة: افتح المكان في Google Maps، اسحب بطاقته للأعلى، وتحت العنوان اضغط <b>Plus code</b> (شكله <b>GV74+C3 London</b> — تظهر Copied)، ارجع واضغط <b>Paste</b>: دبوس واحد دقيق يُفكّ على جهازك بلا أي طلب لـGoogle. وكل بطاقة مثبَّتة تعرض رمزها تحت العنوان، فالتحقق مقارنة سطرين: رمز واحد = موضع واحد. أو أبقِه في قائمتك بلا دبوس (<b>Not pinned yet</b> يعرضها ويحفظها ملفًا). وما لا يُعرف يبقى في الصندوق لك — ومنه الأماكن خارج ضوابط المحتوى (بارات · سهر · كحول · معسل · قمار) تُوسم ولا تُفرز أبدًا.' } },
  { id: 'import.undo', dest: 'import', tags: [], ui: ['Undo last import', 'Pins &amp; import', 'Receipt', 'Resume'],
    en: { h: 'Undo, Receipt, Resume', b: '6. Changed your mind? <b>Undo last import</b> — in ⚙ City (<i>Pins &amp; import</i>) or ☰ → Import — removes what the import added and keeps anything you worked on — pinned, edited, moved, or put in a trip. Choosing the same file again later applies the choices you made and skips places you removed by hand. A <b>Receipt</b> lists what came in. If the app closed mid-way, <b>Resume</b> finishes the cities that were left.' },
    ar: { h: 'التراجع والإيصال والاستكمال (Undo · Receipt · Resume)', b: '٦. غيّرت رأيك؟ <b>Undo last import</b> — في ⚙ City (<i>Pins &amp; import</i>) أو ☰ ← Import — يزيل ما أضافه الاستيراد ويُبقي كل ما عملت عليه — ما ثبّته أو عدّلته أو نقلته أو وضعته في رحلة. واختيار الملف نفسه لاحقًا يطبّق قراراتك ويتخطّى ما أزلته بيدك. و<b>Receipt</b> إيصال بما دخل. وإن أُغلق التطبيق في المنتصف فـ<b>Resume</b> يكمل المدن الباقية.' } },
  { id: 'import.each', dest: 'import', tags: [], ui: [],
    en: { h: 'What happens to each place', b: "· <b>Already in your list</b> → skipped, nothing changes. <b>Same name as an older place of yours</b> (one row, one place) → no twin: the older place gains the map id and the long link, keeps its pin. <b>Looks similar</b> to one you have → kept, marked so you decide.<br>· <b>In a city you don't have yet</b> → the city is created for you.<br>· <b>In a city we don't cover yet</b> → counted and kept out; when its country is known it <b>waits</b> (name and link only, no location) until you add a city there — then “Place them now” brings it in." },
    ar: { h: 'ماذا يحدث لكل مكان', b: '· <b>موجود عندك</b> ← يُتخطّى ولا يتغير شيء. <b>اسمه اسم مكان قديم عندك</b> (صف واحد ومكان واحد) ← لا توأم: القديم يكسب معرّف الخريطة والرابط الطويل ويحتفظ بدبوسه. <b>يشبه مكانًا عندك</b> ← يبقى موسومًا لتقرر أنت.<br>· <b>في مدينة ليست عندك بعد</b> ← تُنشأ لك المدينة.<br>· <b>في مدينة لا نغطيها بعد</b> ← يُعدّ ويبقى خارجًا؛ وإن عُرفت دولته <b>ينتظر</b> (الاسم والرابط فقط، بلا موقع) حتى تضيف مدينة منها — ثم «Place them now» يُدخله.' } },
  { id: 'import.privacy', dest: 'import', tags: [], ui: [],
    en: { h: 'Privacy of your file', b: 'Your Takeout file is read on your device only and never sent. Each place keeps the file’s location in its own link so we can match it on our map; pins come only from our map data, never from the file.' },
    ar: { h: 'خصوصية ملفك', b: 'ملف Takeout يُقرأ في جهازك فقط ولا يُرسل. كل مكان يحتفظ بموقعه من الملف في رابطه لنطابقه على خريطتنا؛ والدبوس من بيانات خريطتنا فقط لا من الملف.' } },
  { id: 'import.after', dest: 'import', tags: ['r98b', 'r97'], ui: ['Merge into another city', 'Split out a town', 'Undo', 'Pins &amp; import', 'Re-read areas from pins', 'Undo last import', 'Duplicates', 'Keep both', 'Drop this row', 'Not pinned yet', 'Pin summary'],
    en: { h: 'After the import', b: '⚙ in the Places row — <i>Merge into another city</i> (its places keep their categories, tagged as a town outside the bigger city), <i>Split out a town</i> (a new city from our list or from its pins), move one place from Edit, <i>🗑 beside a town</i> (remove a folded town with its places), <i>Undo</i>, and under <i>Pins &amp; import</i> <i>Re-read areas from pins</i> and <i>Undo last import</i> — the Pins panel on the map shows only while something is left to pin. The same place twice shows as <i>▸ Duplicates · N</i> in the box above the list — tap a name for its card, keep one, the rest merge into it. During a batch, a row at a spot you already have is held — <i>Keep both</i> or <i>Drop this row</i>. The result screen counts what arrived — places, the lists they came from, and cities; and in each city the <i>Not pinned yet</i> sheet opens with a <i>Pin summary</i>: how many are pinned, how many wait for your pick, how many were not found.' },
    ar: { h: 'بعد الاستيراد', b: '⚙ في صفّ الأماكن — <i>Merge into another city</i> (أماكنها تبقى بتصنيفاتها موسومة بلدةً خارج المدينة الأكبر) · <i>Split out a town</i> (مدينة جديدة من معجمنا أو من دبابيسها) · نقل مكان واحد من Edit · <i>🗑 بجانب البلدة</i> (حذف بلدة مضمومة بأماكنها) · <i>Undo</i> · وتحت <i>Pins &amp; import</i> <i>Re-read areas from pins</i> و<i>Undo last import</i> — ولوحة Pins فوق الخريطة تظهر ما دام شيء ينتظر التثبيت فقط. والمكان نفسه مرتين يظهر صفًّا <i>▸ Duplicates · N</i> في الصندوق فوق القائمة — اضغط الاسم لبطاقته وأبقِ واحدًا والبقية تُدمج فيه. وفي الدفعة يُحجز الصف الذي في موقع لديك أصلًا — <i>Keep both</i> أو <i>Drop this row</i>. وشاشة النتيجة تعدّ ما وصل — الأماكن، والقوائم التي جاءت منها، والمدن؛ وفي كل مدينة تبدأ ورقة <i>Not pinned yet</i> بـ<i>Pin summary</i>: كم ثُبّت، وكم ينتظر اختيارك، وكم لم يُعثر عليه.' } },
  { id: 'privacy.data', dest: 'privacy', tags: ['r116'], ui: ['Nearby'],
    en: { h: 'Your data & privacy', b: 'Your places are yours: download everything as an open file any time, import it back, and delete your account with all its traces. Counters about your public lists and trips (how many views and saves — numbers only, never names) are removed later by a periodic cleanup, not at the same moment. Location is used only when you tap <i>Nearby</i> and is never stored. Following is public to the person you follow. We use open map data with attribution. From a Google Maps link we read only the place name and address to find it in our own data — never its coordinates; the link stays the door. A place saved without a link opens as a search in Google Maps by its name, area, city and country. Your Takeout file is read on your device only and never sent; each place keeps the file’s location in its own link for matching, and pins come only from our map data. MyPickz is not affiliated with Google.' },
    ar: { h: 'بياناتك وخصوصيتك', b: 'أماكنك ملكك: نزّل كل بياناتك بملف مفتوح متى شئت، واستوردها، واحذف حسابك بكل أثره. عدّادات قوائمك ورحلاتك العامة (كم مشاهدة وكم حفظًا — أرقام فقط بلا أسماء) تُزال لاحقًا بتنظيف دوري، لا في اللحظة نفسها. الموقع يُستعمل عند ضغطك «Nearby» فقط ولا يُخزَّن. المتابعة معلنة لمن تتابعه. نستعمل بيانات خرائط مفتوحة بنسبتها. من رابط خرائط جوجل نقرأ اسم المكان وعنوانه فقط لنجده في بياناتنا — لا إحداثياته أبدًا؛ الرابط يبقى الباب. والمكان المحفوظ بلا رابط يُفتح بحثًا في خرائط جوجل باسمه وحيّه ومدينته ودولته. وملف Takeout يُقرأ في جهازك فقط ولا يُرسل؛ كل مكان يحتفظ بموقعه من الملف في رابطه للمطابقة، والدبوس من بيانات خريطتنا فقط. MyPickz ليس تابعًا لجوجل.' } },
  { id: 'howto.links', dest: 'howto', tags: [], ui: [],
    en: { h: 'How to copy a link & export your lists', b: '<b>A place link:</b> open the place in Google Maps → Share → Copy → back in MyPickz: ＋ Add place → Paste from Maps.<br><b>Your saved lists:</b> Google Takeout → Deselect all → tick "Saved" and "Maps (your places)" → Create export → download the .zip from Google’s email → MyPickz → ☰ → Import.<br><b>On Android:</b> add MyPickz to your home screen from Chrome first; then in Google Maps tap Share → MyPickz — the place opens in ＋ Add place, read and ready to save (with no city open, pick one first: it waits). On iPhone, copy the link and paste it.' },
    ar: { h: 'كيف تنسخ رابطًا وتصدّر قوائمك', b: '<b>رابط المكان:</b> افتح المكان بخرائط جوجل ← مشاركة ← نسخ ← بالتطبيق: ＋ Add place ← Paste from Maps.<br><b>قوائمك المحفوظة:</b> Google Takeout ← Deselect all ← اختر «Saved» و«Maps (your places)» ← Create export ← نزّل الملف المضغوط من بريد جوجل ← بالتطبيق: ☰ ← Import.<br><b>على أندرويد:</b> أضف MyPickz إلى الشاشة الرئيسية من Chrome أولًا؛ ثم في خرائط جوجل: مشاركة ← MyPickz — يُفتح المكان في ＋ Add place مقروءًا وجاهزًا للحفظ (وبلا مدينة مفتوحة اختر مدينة أولًا: ينتظرك). على الآيفون انسخ الرابط والصقه.' } },
  { id: 'settings.doors', dest: 'settings', tags: [], ui: ['Nickname', 'Password', 'Email', 'Home screen', 'Export language', 'Log out', 'Delete account'],
    en: { h: 'Settings', b: 'Account: <i>Nickname</i> · <i>Password</i> · <i>Email</i>. Preferences: <i>Home screen</i> (auto or your choice) · <i>Export language</i>. Then <i>Log out</i> and <i>Delete account</i>.' },
    ar: { h: 'الإعدادات', b: 'الحساب: <i>Nickname</i> · <i>Password</i> · <i>Email</i>. التفضيلات: <i>Home screen</i> (تلقائي أو اختيارك) · <i>Export language</i>. ثم <i>Log out</i> و<i>Delete account</i>.' } },
  { id: 'home.shortcut', dest: 'home', tags: [], ui: [],
    en: { h: 'Adding MyPickz to your Home Screen or Desktop, on mobile or computer', b: '1. Open the site in your browser (Safari or others)<br>2. Tap the Share button on mobile, or the options menu on desktop<br>3. Choose "Add to Home Screen" (mobile) or "Create Shortcut" (desktop)<br>4. Now you can open MyPickz with one tap, like any other app' },
    ar: { h: 'إضافة MyPickz إلى سطح المكتب سواء في جهاز الجوال أو الكمبيوتر', b: '1. افتح الموقع من المتصفح (Safari أو غيره)<br>2. اضغط زر المشاركة (Share) على الجوال، أو قائمة الخيارات على الكمبيوتر<br>3. اختر "Add to Home Screen" (جوال) أو "Create Shortcut" (كمبيوتر)<br>4. الآن يمكنك فتح MyPickz بضغطة واحدة، تمامًا كأي تطبيق آخر' } },
];
function helpTopicsOf(id){ return HELP_TOPICS.filter(function(t){ return t.dest === id; }); }


function setHelpLang(lang){ /* ب-٢-٢-أ٢ (v3 · ١٤): مبدّل اللغة شريحتان مقطعيتان تحت رأس القشرة */
  helpLang = lang; try{ localStorage.setItem('mp_help_lang', lang === 'ar' ? 'ar' : 'en'); }catch(_){}
  document.getElementById('helpLangArBtn').classList.toggle('on', lang === 'ar');
  document.getElementById('helpLangEnBtn').classList.toggle('on', lang === 'en');
  renderHelpModal();
}

function helpToggleTopic(id){ helpOpenTopic = (helpOpenTopic === id) ? '' : id; renderHelpModal(); const el = document.getElementById('help_top_' + id.replace('.', '_')); if (el && el.scrollIntoView) el.scrollIntoView({ block: 'nearest' }); }
function helpOpenGroup(id){ /* بطاقة ← مواضيعها مطوية بعناوينها · '' ← المستوى الأول · المجموعة ذات الموضوع الواحد تفتحه */ helpView = id || null; const ts = id ? helpTopicsOf(id) : []; helpOpenTopic = ts.length === 1 ? ts[0].id : ''; renderHelpModal(); const w = document.getElementById('helpSections'); if (w) w.scrollTop = 0; }
function helpAct(id){ /* فعل البطاقة: يغلق الإرشاد وينفّذ ما تصفه */ if (!currentUser) return; closeHelpModal(); if (id === 'places'){ switchTab('Places'); if (placesSource !== 'mine') selectPlacesSource('mine'); if (!cityListCityId) plAddCity(); else if (plPanel !== 'cats') plTogglePanel('cats'); } else if (id === 'trips'){ switchTab('Trips'); openTripBuilder(); } else if (id === 'curators') switchTab('Curators'); else if (id === 'community') switchTab('Community'); else if (id === 'addresses') switchTab('Addresses'); }
function helpTabIcon(id){ /* أيقونة الوجهة من الشريط السفلي نفسه — مصدر واحد */ const el = document.querySelector('#mpTabbar [data-tab="' + id.charAt(0).toUpperCase() + id.slice(1) + '"] .ti'); return el ? '<span class="help-card-ic" aria-hidden="true">' + el.innerHTML + '</span>' : ''; }
function helpCardHtml(id, inView){ /* r115-أ: بطاقة الوجهة — أيقونتها · اسمها وجملتها · فعل ينفّذ ويغلق · شرح متحرّك · مواضيعها */
  const data = HELP_CONTENT[helpLang], d = data.intro.dests[HELP_DESTS.indexOf(id)];
  return '<div class="help-card" id="help_card_' + id + '"><div class="help-card-t">' + helpTabIcon(id) + '<span><b>' + d[0] + '</b> — ' + d[1] + '</span></div><div class="chiprow help-card-a">'
    + (currentUser ? '<button type="button" dir="ltr" class="chip sm on" onclick="helpAct(\'' + id + '\')">' + HELP_ACT[id] + '</button>' : '')
    + (HELP_DEMOS[id] ? '<button type="button" dir="ltr" class="chip sm" onclick="helpDemoOpen(\'' + id + '\')">▶ Show me</button>' : '')
    + (inView ? '' : '<button type="button" class="chip sm" onclick="helpOpenGroup(\'' + id + '\')">' + data.topics + ' <span class="arr">›</span></button>')
    + '</div><div id="helpDemoHost_' + id + '"></div></div>'; }
function helpTopicHtml(t){ const open = helpOpenTopic === t.id, x = t[helpLang === 'ar' ? 'ar' : 'en'];
  return '<div class="help-topic" id="help_top_' + t.id.replace('.', '_') + '"><button type="button" class="help-topic-h" onclick="helpToggleTopic(\'' + t.id + '\')"><span>' + x.h + '</span><span class="arr">' + (open ? '▲' : '▼') + '</span></button>'
    + (open ? '<div class="help-topic-b">' + x.b + (t.id === 'privacy.data' ? '<div class="help-counters">' + escapeHtml(mpTripCountersLine()) + '<br>' + escapeHtml(tkImportLine()) + ' <button type="button" class="actn" onclick="mpTripCountersReset()">Reset</button></div>' : '') + '</div>' : '') + '</div>'; }
function renderHelpModal(){
  if (helpDemo) helpDemoClose(); /* إعادة الرسم تزيل مسرح العرض — يُغلق بمؤقّته أولًا */
  const data = HELP_CONTENT[helpLang]; const ar = helpLang === 'ar';
  document.getElementById('helpTitle').textContent = data.title;
  const wrap = document.getElementById('helpSections'); wrap.style.direction = ar ? 'rtl' : 'ltr'; wrap.style.textAlign = ar ? 'right' : 'left';
  const it = data.intro; let h;
  if (!helpView){ /* المستوى الأول: التعريف · خمس بطاقات بترتيب الشريط السفلي · شريط «Everywhere» لما يعبر الوجهات · ابدأ بسرعة */
    h = '<div class="help-l1" style="font-size:13px; line-height:1.75;">'
      + '<p style="margin:0 0 8px;">' + it.def + '</p>'
      + '<p class="help-feats" style="margin:0 0 10px; font-size:11.5px; font-weight:700; color:var(--saffron);">' + it.feats + '</p>'
      + HELP_DESTS.map(function(id){ return helpCardHtml(id, false); }).join('')
      + '<div class="help-card" id="help_card_everywhere"><div class="help-card-t"><span><b>' + data.everywhereH + '</b> — ' + it.everywhere + '</span></div><div class="chiprow help-card-a">'
      + HELP_EVERYWHERE.map(function(id){ return '<button type="button" class="chip sm" onclick="helpOpenGroup(\'' + id + '\')">' + HELP_GROUP_H[id][ar ? 1 : 0] + ' <span class="arr">›</span></button>'; }).join('') + '</div></div>'
      + '<p style="margin:0 0 10px;">' + it.start + '</p></div>';
  } else { /* المستوى الثاني: بطاقة الوجهة ثم مواضيعها مطوية بعناوينها */
    h = '<button type="button" class="btn btn-ghost help-back" onclick="helpOpenGroup(\'\')">' + data.back + '</button>'
      + (HELP_DESTS.indexOf(helpView) >= 0 ? helpCardHtml(helpView, true) : '<div class="help-group-h">' + HELP_GROUP_H[helpView][ar ? 1 : 0] + '</div>')
      + helpTopicsOf(helpView).map(helpTopicHtml).join('');
  }
  wrap.innerHTML = h;
  wrap.innerHTML += '<div class="chipgrid c3" style="margin-top:6px;"><button type="button" class="pl-src" onclick="closeHelpModal(); copyLink();">🔗 Copy link</button><button type="button" class="pl-src" onclick="closeHelpModal(); showQR();">🀄 QR</button><a class="pl-src" href="mailto:mypickz.app@gmail.com?subject=MyPickz%20Feedback">✉️ Contact us</a></div>'; // ر٧٢-أ-١: «Share the app» داخل Help (المرجع §٧)
  const cb = document.getElementById('helpCloseBtn'); cb.textContent = currentUser ? data.closeLabel : data.gotIt; // أ-١٢-٢: للزائر «Got it — sign in»
}
/* ═══ r115-أ (ق١١-١١-٠٤ «الشرح متحرك» · بيان r115 §٢-ب): الشرح المتحرّك — كل خطوة تُرسم بدوال الشاشة الحقيقية نفسها على بيانات نموذجية، داخل مسرح مصغَّر، ومؤشّر يتحرّك إلى الزر المقصود.
   لا صور ولا فيديو: ما يراه المستخدم هو شكل الشاشة في بنائه. القياس (١١ نوفمبر): tbStage1Html و tbDraftHtml تُرسمان بحالة محرّر نموذجية تُبدَّل مؤقتًا ثم تعود — بلا أثر في TB ولا userTrips ولا ذاكرة الجهاز.
   ضد التقادم: كل خطوة تسمّي الزر (ui) ومعالجه (fn) ومحدِّده (point)؛ التدقيق يُسقط البناء إن غاب المعالج، ومحطة تشغّل العرض وتتحقق أن المحدِّد يجد زرّه في كل خطوة. ═══ */
function helpDemoSandbox(fn){ /* حالة المحرّر تُبدَّل للرسم وحده (متزامن) ثم تعود كما كانت — والرحلة النموذجية التي ينشئها مسار الرسم تُزال */
  const s = { TB: (typeof TB === 'undefined') ? null : TB, cur: currentTripId }; let demoId = null;
  try{ return fn(function(id){ demoId = id; }); }
  finally { try{ if (TB && TB.__demo && TB.tripId) demoId = TB.tripId; }catch(_){} TB = s.TB; currentTripId = s.cur; if (demoId){ const i = (userTrips || []).findIndex(function(t){ return t.id === demoId; }); if (i >= 0) userTrips.splice(i, 1); delete resolvedTripCache[demoId]; delete tripSavedJson[demoId]; } }
}
function helpDemoClone(sel, fill, hide){ /* نافذة مرسومة في الصفحة نفسها (HTML ثابت): نسخة منها بلا معرّفات — لا id مكرَّر — وخاناتها بقيم نموذجية. الأصل لا يُمسّ */
  const src = document.querySelector(sel); if (!src) return ''; const c = src.cloneNode(true);
  c.querySelectorAll('[id]').forEach(function(el){ const id = el.id; el.removeAttribute('id'); el.setAttribute('data-hid', id); const v = fill ? fill[id] : undefined; if (hide && hide.indexOf(id) >= 0){ el.style.display = 'none'; return; } if (v === undefined) return; if (el.tagName === 'INPUT') el.setAttribute('value', v); else if (el.tagName === 'TEXTAREA') el.textContent = v; else el.innerHTML = v; if (el.style && el.style.display === 'none') el.style.display = ''; });
  return c.innerHTML; }
function helpDemoListCard(uid, nick, cityId, city, n){ /* بطاقة قائمة عامة كما يرسمها المجتمع والمنتقون (othersCard) تحت كبسولة صاحبها */
  return placeGroupHtml(nick, 1, '', othersCard({ title: escapeHtml(city), sub: 'Places · ' + n, stat: '128 views', bmSelf: false, bmOn: false, cnt: 3, bmHandler: "toggleListBookmark('" + uid + "', '" + cityId + "')", reportKind: 'list', reportKey: uid + '_' + cityId, saveHandler: "saveOthersList('" + uid + "', '" + cityId + "')", savedOn: false, unsaveHandler: '', exportHandler: "openExportPreview('olist', '" + uid + '_' + cityId + "')", openHandler: "cmOpenList('" + uid + "', '" + cityId + "')" }), 'city'); }
