    const off = ['plDeleteBtn', 'plCityHint', 'plPlusErr', 'plTownHold'], fresh = { plPlaceTitle: '➕ Add a place', plUrlLine: '', plModalCity: 'Lisbon' }; /* النافذة الحقيقية تحمل حال آخر فتح (Edit · Delete) — العرض يعيدها لحال الإضافة */
