function helpDemoOpen(id){ const d = HELP_DEMOS[id]; if (!d || !document.getElementById('helpDemoHost_' + id)) return; helpDemoClose(); const host = document.getElementById('helpDemoHost_' + id); let frames = []; try{ frames = d.build() || []; }catch(e){ mpSwallow(e, 'help-demo'); } if (!frames.length){ showToast('Could not draw this walkthrough'); return; }
  helpDemo = { id: id, frames: frames, i: 0, timer: null };
  host.innerHTML = '<div class="hdm"><div class="hdm-head"><b>' + escapeHtml(d.title[helpLang === 'ar' ? 'ar' : 'en']) + '</b><button type="button" class="chip sm" onclick="helpDemoClose()" aria-label="Close">✕</button></div>'
    + '<div class="hdm-stage" id="hdStage" inert aria-hidden="true"><div class="hdm-move" id="hdMove"><div class="modal night tbuild hdm-in" id="hdIn"></div></div><span class="hdm-ring" id="hdRing"></span><span class="hdm-ptr" id="hdPtr"></span></div>'
    + '<div class="hdm-cap" id="hdCap" dir="auto"></div><div class="hdm-ctl"><button type="button" class="chip sm" onclick="helpDemoStep(-1)" aria-label="Previous step">‹</button><span class="hdm-n" id="hdN" dir="ltr"></span><button type="button" class="chip sm" onclick="helpDemoStep(1)" aria-label="Next step">›</button><button type="button" class="chip sm" onclick="helpDemoGo(0)" aria-label="Replay">↻</button></div></div>';
  helpDemoGo(0); try{ host.scrollIntoView({ block: 'nearest' }); }catch(_){} }
function helpDemoClose(){ if (helpDemo && helpDemo.timer) clearTimeout(helpDemo.timer); const host = helpDemo ? document.getElementById('helpDemoHost_' + helpDemo.id) : null; helpDemo = null; if (host) host.innerHTML = ''; }
function helpDemoStep(dir){ if (!helpDemo) return; helpDemoGo((helpDemo.i + dir + helpDemo.frames.length) % helpDemo.frames.length, true); }
function helpDemoGo(i, manual){ const d = helpDemo; if (!d) return; if (d.timer){ clearTimeout(d.timer); d.timer = null; } d.i = i; const f = d.frames[i]; const inn = document.getElementById('hdIn'), mv = document.getElementById('hdMove'), st = document.getElementById('hdStage'), ptr = document.getElementById('hdPtr'), ring = document.getElementById('hdRing'); if (!inn || !st) return;
  if (inn.__html !== f.html){ inn.className = (f.wrap || 'modal night tbuild') + ' hdm-in'; inn.innerHTML = f.html; inn.__html = f.html; inn.querySelectorAll('[id]').forEach(function(el){ el.setAttribute('data-hid', el.id); el.removeAttribute('id'); }); inn.querySelectorAll('a, button, input, select, textarea, [tabindex]').forEach(function(el){ el.setAttribute('tabindex', '-1'); }); /* r115 (مراجعة مستقلة): الشاشة داخل المسرح صورة لا تُضغط — بلا معرّفات (لا تكرار id مع الشاشة الحقيقية) وخارج ترتيب لوحة المفاتيح؛ والمسرح inert */ } /* الخطوات المتتالية على الشاشة نفسها لا تُعاد رسمًا — المسرح يتحرّك إليها */
  document.getElementById('hdCap').textContent = f[helpLang === 'ar' ? 'ar' : 'en']; document.getElementById('hdN').textContent = (i + 1) + ' / ' + d.frames.length;
  const el = inn.querySelector(f.point); d.found = !!el; const prev = mv.__shift || 0;
  mv.style.transition = 'none'; mv.style.transform = 'translateY(0px)'; void mv.offsetHeight; /* القياس والمسرح في موضعه الأصلي وبلا حركة جارية — كان يُقاس في منتصف الانتقال فتقع الحلقة فوق زر آخر */
  if (el){ const sr = st.getBoundingClientRect(); const er = el.getBoundingClientRect(); const shift = Math.max(0, Math.round((er.top - sr.top) - sr.height * 0.42)); mv.style.transform = 'translateY(' + (-prev) + 'px)'; void mv.offsetHeight; mv.style.transition = ''; mv.style.transform = 'translateY(' + (-shift) + 'px)'; mv.__shift = shift; const x = er.left - sr.left, y = er.top - sr.top - shift;
    ring.style.cssText = 'display:block; left:' + (x - 4) + 'px; top:' + (y - 4) + 'px; width:' + (er.width + 8) + 'px; height:' + (er.height + 8) + 'px;'; ptr.style.cssText = 'display:block; left:' + (x + er.width - 14) + 'px; top:' + (y + er.height - 12) + 'px;'; /* على الركن السفلي الأيمن للزر — اسمه وعدّاده يبقيان مقروءين */ ptr.classList.remove('tap'); void ptr.offsetWidth; ptr.classList.add('tap'); }
  else { mv.style.transition = ''; mv.__shift = 0; ring.style.display = 'none'; ptr.style.display = 'none'; }
  if (!manual && !helpDemoReduced() && i + 1 < d.frames.length) d.timer = setTimeout(function(){ if (helpDemo === d) helpDemoGo(i + 1); }, HELP_DEMO_MS); /* يتقدّم وحده إلى آخر خطوة ثم يقف؛ الضغط على ‹ › يوقف التقدّم · ومع «تقليل الحركة» لا تقدّم تلقائي */
}
